// A component = a TS class + template + styles. The CLI scaffolds it.
@Component({
  selector: 'app-counter',
  template: `<button (click)="inc()">{{count}}</button>`,
})
export class CounterComponent {
  count = 0;
  inc() { this.count++; }     // change detection sees the mutation -> updates DOM
}

// Dependency injection: a service is injectable; the component receives it.
@Injectable({ providedIn: 'root' })        // one instance app-wide
export class CartService { items = signal(0); }

@Component({ /* ... */ })
export class CartComponent {
  constructor(private cart: CartService) {} // ANGULAR injects it
}
//   DI makes the service mockable in tests and decoupled from the component.

// Change detection strategy: OnPush checks this component only when its
//   @Input() references change or an event fires -> big perf win.
@Component({ /* ... */, changeDetection: ChangeDetectionStrategy.OnPush })
export class HeavyComponent { @Input() data!: Item[]; }
